#include <cstdint>
#include <string>

std::uint32_t crc32(const std::string& data)
{
    std::uint32_t crc{ 0xFFFFFFFFu };
    for (unsigned char byte : data)
    {
        crc ^= byte;
        for (int bit{ 0 }; bit < 8; ++bit)
            crc = (crc & 1u) ? (crc >> 1) ^ 0xEDB88320u : crc >> 1;
    }
    return crc ^ 0xFFFFFFFFu;
}

bool verify(const std::string& data, std::uint32_t expected)
{
    return crc32(data) == expected;
}

unitTests:
TEST("the empty string") { CHECK_EQ(crc32(""), 0x00000000u); }
TEST("the standard check value") { CHECK_EQ(crc32("123456789"), 0xCBF43926u); }
TEST("a single letter") { CHECK_EQ(crc32("a"), 0xE8B7BE43u); }
TEST("a sentence") { CHECK_EQ(crc32("The quick brown fox jumps over the lazy dog"), 0x414FA339u); }
TEST("bytes above 127") { CHECK_EQ(crc32(std::string("\xFF\x00\x80", 3)), crc32(std::string("\xFF\x00\x80", 3))); CHECK(crc32(std::string("\xFF", 1)) != crc32(std::string("\x7F", 1))); }
TEST("verify spots a changed byte") { CHECK(verify("gold=1250", crc32("gold=1250"))); CHECK(!verify("gold=9250", crc32("gold=1250"))); }

